import React, { useState } from 'react';

// Körperzonen – jeweils mit einem SVG-Pfad und einem lesbaren Namen
const FRONT_PARTS = [
  { id: 'forehead',         label: 'Stirn',                  cx: 50, cy: 8,   rx: 8,  ry: 5 },
  { id: 'face',             label: 'Gesicht',                cx: 50, cy: 14,  rx: 9,  ry: 8 },
  { id: 'neck-front',       label: 'Hals',                   cx: 50, cy: 26,  rx: 4,  ry: 6 },
  { id: 'shoulder-left',    label: 'Schulter links',         cx: 32, cy: 33,  rx: 7,  ry: 6 },
  { id: 'shoulder-right',   label: 'Schulter rechts',        cx: 68, cy: 33,  rx: 7,  ry: 6 },
  { id: 'chest',            label: 'Brust',                  cx: 50, cy: 43,  rx: 10, ry: 10 },
  { id: 'abdomen',          label: 'Bauch',                  cx: 50, cy: 60,  rx: 11, ry: 12 },
  { id: 'upper-arm-left',   label: 'Oberarm links',          cx: 25, cy: 42,  rx: 6,  ry: 10 },
  { id: 'upper-arm-right',  label: 'Oberarm rechts',         cx: 75, cy: 42,  rx: 6,  ry: 10 },
  { id: 'forearm-left',     label: 'Unterarm links',         cx: 18, cy: 58,  rx: 5,  ry: 12 },
  { id: 'forearm-right',    label: 'Unterarm rechts',        cx: 82, cy: 58,  rx: 5,  ry: 12 },
  { id: 'palm-left',        label: 'Handinnenfläche links',  cx: 14, cy: 72,  rx: 5,  ry: 6 },
  { id: 'palm-right',       label: 'Handinnenfläche rechts', cx: 86, cy: 72,  rx: 5,  ry: 6 },
  { id: 'hip-left',         label: 'Hüfte links',            cx: 38, cy: 75,  rx: 7,  ry: 6 },
  { id: 'hip-right',        label: 'Hüfte rechts',           cx: 62, cy: 75,  rx: 7,  ry: 6 },
  { id: 'groin',            label: 'Intimbereich',           cx: 50, cy: 80,  rx: 6,  ry: 5 },
  { id: 'thigh-left',       label: 'Oberschenkel links',     cx: 40, cy: 97,  rx: 7,  ry: 14 },
  { id: 'thigh-right',      label: 'Oberschenkel rechts',    cx: 60, cy: 97,  rx: 7,  ry: 14 },
  { id: 'knee-left',        label: 'Knie links',             cx: 40, cy: 112, rx: 6,  ry: 5 },
  { id: 'knee-right',       label: 'Knie rechts',            cx: 60, cy: 112, rx: 6,  ry: 5 },
  { id: 'shin-left',        label: 'Schienbein links',       cx: 40, cy: 127, rx: 5,  ry: 12 },
  { id: 'shin-right',       label: 'Schienbein rechts',      cx: 60, cy: 127, rx: 5,  ry: 12 },
  { id: 'foot-left',        label: 'Fuß links',              cx: 40, cy: 142, rx: 6,  ry: 4 },
  { id: 'foot-right',       label: 'Fuß rechts',             cx: 60, cy: 142, rx: 6,  ry: 4 },
];

const BACK_PARTS = [
  { id: 'head-back',           label: 'Kopf',                       cx: 50, cy: 12,  rx: 10, ry: 9 },
  { id: 'neck-back',           label: 'Hals',                       cx: 50, cy: 26,  rx: 4,  ry: 6 },
  { id: 'back',                label: 'Rücken',                     cx: 50, cy: 52,  rx: 11, ry: 16 },
  { id: 'upper-arm-left-back', label: 'Oberarm links',              cx: 25, cy: 42,  rx: 6,  ry: 10 },
  { id: 'upper-arm-right-back',label: 'Oberarm rechts',             cx: 75, cy: 42,  rx: 6,  ry: 10 },
  { id: 'elbow-left',          label: 'Ellenbogen links',           cx: 20, cy: 54,  rx: 5,  ry: 4 },
  { id: 'elbow-right',         label: 'Ellenbogen rechts',          cx: 80, cy: 54,  rx: 5,  ry: 4 },
  { id: 'forearm-left-back',   label: 'Unterarm links',             cx: 18, cy: 65,  rx: 5,  ry: 12 },
  { id: 'forearm-right-back',  label: 'Unterarm rechts',            cx: 82, cy: 65,  rx: 5,  ry: 12 },
  { id: 'palm-back-left',      label: 'Handaußenfläche links',      cx: 14, cy: 78,  rx: 5,  ry: 6 },
  { id: 'palm-back-right',     label: 'Handaußenfläche rechts',     cx: 86, cy: 78,  rx: 5,  ry: 6 },
  { id: 'glute-left',          label: 'Gesäß links',                cx: 40, cy: 73,  rx: 8,  ry: 8 },
  { id: 'glute-right',         label: 'Gesäß rechts',               cx: 60, cy: 73,  rx: 8,  ry: 8 },
  { id: 'thigh-back-left',     label: 'Oberschenkel hinten links',  cx: 40, cy: 97,  rx: 7,  ry: 14 },
  { id: 'thigh-back-right',    label: 'Oberschenkel hinten rechts', cx: 60, cy: 97,  rx: 7,  ry: 14 },
  { id: 'calf-left',           label: 'Wade links',                 cx: 40, cy: 125, rx: 5,  ry: 13 },
  { id: 'calf-right',          label: 'Wade rechts',                cx: 60, cy: 125, rx: 5,  ry: 13 },
  { id: 'heel-left',           label: 'Ferse links',                cx: 38, cy: 141, rx: 5,  ry: 4 },
  { id: 'heel-right',          label: 'Ferse rechts',               cx: 62, cy: 141, rx: 5,  ry: 4 },
];

function BodySVG({ parts, selected, onToggle, label }) {
  return (
    <div className="body-model-view">
      <span className="body-view-label">{label}</span>
      <svg
        viewBox="0 0 100 160"
        className="body-svg"
        style={{ width: 75, height: 140 }}
      >
        {/* KOPF */}
        <circle cx="50" cy="12" r="9" fill="none" stroke="#333" strokeWidth="1" />
        
        {/* GESICHT - einfache Linien */}
        <line x1="47" y1="10" x2="47" y2="13" stroke="#333" strokeWidth="0.6" />
        <line x1="53" y1="10" x2="53" y2="13" stroke="#333" strokeWidth="0.6" />
        <path d="M 47 14 Q 50 15 53 14" stroke="#333" strokeWidth="0.6" fill="none" />

        {/* HALS */}
        <line x1="46" y1="21" x2="44" y2="28" stroke="#333" strokeWidth="1" />
        <line x1="54" y1="21" x2="56" y2="28" stroke="#333" strokeWidth="1" />

        {/* OBERKÖRPER - realistische Konturen */}
        <path d="M 44 28 L 38 35 Q 35 40 35 50 L 35 70 Q 37 72 44 73 L 56 73 Q 63 72 65 70 L 65 50 Q 65 40 62 35 L 56 28" 
              stroke="#333" strokeWidth="1" fill="none" strokeLinecap="round" strokeLinejoin="round" />

        {/* SCHULTER-DETAILS */}
        <line x1="38" y1="35" x2="35" y2="37" stroke="#333" strokeWidth="0.8" />
        <line x1="62" y1="35" x2="65" y2="37" stroke="#333" strokeWidth="0.8" />

        {/* BRUSTMITTE - Linie */}
        <line x1="50" y1="30" x2="50" y2="65" stroke="#ddd" strokeWidth="0.6" opacity="0.6" />

        {/* OBERARME */}
        <line x1="38" y1="37" x2="28" y2="42" stroke="#333" strokeWidth="1" strokeLinecap="round" />
        <line x1="62" y1="37" x2="72" y2="42" stroke="#333" strokeWidth="1" strokeLinecap="round" />

        {/* UNTERARME */}
        <line x1="28" y1="42" x2="20" y2="62" stroke="#333" strokeWidth="1" strokeLinecap="round" />
        <line x1="72" y1="42" x2="80" y2="62" stroke="#333" strokeWidth="1" strokeLinecap="round" />

        {/* HÄNDE */}
        <circle cx="18" cy="72" r="3.5" fill="none" stroke="#333" strokeWidth="0.8" />
        <circle cx="82" cy="72" r="3.5" fill="none" stroke="#333" strokeWidth="0.8" />

        {/* BAUCH - Wölbung */}
        <path d="M 40 60 Q 38 65 40 70 L 50 72 L 60 70 Q 62 65 60 60" 
              stroke="#333" strokeWidth="0.8" fill="none" opacity="0.7" />

        {/* BECKEN / HÜFTEN */}
        <path d="M 35 73 Q 32 75 32 80 L 50 82 L 68 80 Q 68 75 65 73" 
              stroke="#333" strokeWidth="0.9" fill="none" strokeLinecap="round" />

        {/* OBERSCHENKEL - realistische Linien */}
        <path d="M 38 82 Q 37 90 38 105" stroke="#333" strokeWidth="1" fill="none" strokeLinecap="round" />
        <path d="M 42 82 Q 43 90 42 105" stroke="#333" strokeWidth="1" fill="none" strokeLinecap="round" />
        
        <path d="M 58 82 Q 59 90 58 105" stroke="#333" strokeWidth="1" fill="none" strokeLinecap="round" />
        <path d="M 62 82 Q 63 90 62 105" stroke="#333" strokeWidth="1" fill="none" strokeLinecap="round" />

        {/* KNIE - kleine Verbindungen */}
        <line x1="38" y1="105" x2="36" y2="108" stroke="#333" strokeWidth="0.8" />
        <line x1="42" y1="105" x2="44" y2="108" stroke="#333" strokeWidth="0.8" />
        
        <line x1="58" y1="105" x2="56" y2="108" stroke="#333" strokeWidth="0.8" />
        <line x1="62" y1="105" x2="64" y2="108" stroke="#333" strokeWidth="0.8" />

        {/* SCHIENBEIN - realistische Linien */}
        <path d="M 36 108 L 35 135" stroke="#333" strokeWidth="1" fill="none" strokeLinecap="round" />
        <path d="M 44 108 L 45 135" stroke="#333" strokeWidth="1" fill="none" strokeLinecap="round" />
        
        <path d="M 56 108 L 55 135" stroke="#333" strokeWidth="1" fill="none" strokeLinecap="round" />
        <path d="M 64 108 L 65 135" stroke="#333" strokeWidth="1" fill="none" strokeLinecap="round" />

        {/* FÜSSE */}
        <ellipse cx="40" cy="140" rx="6" ry="3.5" fill="none" stroke="#333" strokeWidth="1" />
        <ellipse cx="60" cy="140" rx="6" ry="3.5" fill="none" stroke="#333" strokeWidth="1" />

        {/* Klickbare Zonen */}
        {parts.map(part => {
          const isSelected = selected.includes(part.id);
          return (
            <ellipse
              key={part.id}
              cx={part.cx}
              cy={part.cy}
              rx={part.rx}
              ry={part.ry}
              fill={isSelected ? 'rgba(220,38,38,0.6)' : 'rgba(37,99,235,0.0)'}
              stroke={isSelected ? '#dc2626' : 'transparent'}
              strokeWidth={isSelected ? 1.2 : 0}
              onClick={() => onToggle(part.id, part.label)}
              style={{ cursor: 'pointer' }}
            >
              <title>{part.label}</title>
            </ellipse>
          );
        })}

        {/* Hover-Overlay */}
        {parts.map(part => (
          <ellipse
            key={`hover-${part.id}`}
            cx={part.cx}
            cy={part.cy}
            rx={part.rx}
            ry={part.ry}
            fill="transparent"
            stroke="transparent"
            onClick={() => onToggle(part.id, part.label)}
            style={{ cursor: 'pointer' }}
            onMouseEnter={e => { if (!selected.includes(part.id)) e.target.setAttribute('fill', 'rgba(37,99,235,0.15)'); }}
            onMouseLeave={e => { if (!selected.includes(part.id)) e.target.setAttribute('fill', 'transparent'); }}
          />
        ))}
      </svg>
    </div>
  );
}

function BackBodySVG({ parts, selected, onToggle, label }) {
  return (
    <div className="body-model-view">
      <span className="body-view-label">{label}</span>
      <svg
        viewBox="0 0 100 160"
        className="body-svg"
        style={{ width: 75, height: 140 }}
      >
        <defs>
          <style>{`
            .body-fill { fill: #f5f5f5; stroke: #999; stroke-width: 0.8; }
          `}</style>
        </defs>

        {/* KOPF */}
        <ellipse cx="50" cy="12" rx="10" ry="9" className="body-fill" />

        {/* HALS */}
        <path d="M 46 22 L 44 28 L 56 28 L 54 22" className="body-fill" />

        {/* RÜCKEN */}
        <ellipse cx="50" cy="52" rx="11" ry="16" className="body-fill" />
        
        {/* WIRBELSÄULE - sichtbare Linie */}
        <line x1="50" y1="36" x2="50" y2="68" stroke="#ccc" strokeWidth="1" opacity="0.7" />

        {/* OBERARME */}
        <rect x="23" y="37" width="5" height="14" rx="2.5" className="body-fill" />
        <rect x="72" y="37" width="5" height="14" rx="2.5" className="body-fill" />

        {/* ELLENBOGEN */}
        <ellipse cx="20" cy="54" rx="5" ry="4" className="body-fill" />
        <ellipse cx="80" cy="54" rx="5" ry="4" className="body-fill" />

        {/* UNTERARME */}
        <rect x="15" y="60" width="5" height="12" rx="2.5" className="body-fill" />
        <rect x="80" y="60" width="5" height="12" rx="2.5" className="body-fill" />

        {/* HÄNDE / HANDAUSSENFLÄCHEN */}
        <ellipse cx="14" cy="78" rx="5" ry="6" className="body-fill" />
        <ellipse cx="86" cy="78" rx="5" ry="6" className="body-fill" />

        {/* GESÄSS LINKS */}
        <ellipse cx="40" cy="73" rx="8" ry="8" className="body-fill" />
        
        {/* GESÄSS RECHTS */}
        <ellipse cx="60" cy="73" rx="8" ry="8" className="body-fill" />

        {/* OBERSCHENKEL HINTEN LINKS - schlanker */}
        <path d="M 36 85 Q 35 98 38 110 L 42 110 Q 44 98 42 85 Z" className="body-fill" />
        
        {/* OBERSCHENKEL HINTEN RECHTS - schlanker */}
        <path d="M 64 85 Q 65 98 62 110 L 58 110 Q 56 98 58 85 Z" className="body-fill" />

        {/* WADE LINKS */}
        <path d="M 38 112 L 37 135 Q 40 138 42 138 L 42 115 Z" className="body-fill" />
        
        {/* WADE RECHTS */}
        <path d="M 62 112 L 63 135 Q 60 138 58 138 L 58 115 Z" className="body-fill" />

        {/* FERSE LINKS */}
        <ellipse cx="38" cy="141" rx="5" ry="4" className="body-fill" />
        
        {/* FERSE RECHTS */}
        <ellipse cx="62" cy="141" rx="5" ry="4" className="body-fill" />

        {/* Klickbare Zonen */}
        {parts.map(part => {
          const isSelected = selected.includes(part.id);
          return (
            <ellipse
              key={part.id}
              cx={part.cx}
              cy={part.cy}
              rx={part.rx}
              ry={part.ry}
              fill={isSelected ? 'rgba(220,38,38,0.6)' : 'rgba(37,99,235,0.0)'}
              stroke={isSelected ? '#dc2626' : 'transparent'}
              strokeWidth={isSelected ? 1.2 : 0}
              onClick={() => onToggle(part.id, part.label)}
              style={{ cursor: 'pointer' }}
            >
              <title>{part.label}</title>
            </ellipse>
          );
        })}

        {/* Hover-Overlay */}
        {parts.map(part => (
          <ellipse
            key={`hover-${part.id}`}
            cx={part.cx}
            cy={part.cy}
            rx={part.rx}
            ry={part.ry}
            fill="transparent"
            stroke="transparent"
            onClick={() => onToggle(part.id, part.label)}
            style={{ cursor: 'pointer' }}
            onMouseEnter={e => { if (!selected.includes(part.id)) e.target.setAttribute('fill', 'rgba(37,99,235,0.15)'); }}
            onMouseLeave={e => { if (!selected.includes(part.id)) e.target.setAttribute('fill', 'transparent'); }}
          />
        ))}
      </svg>
    </div>
  );
}

export default function BodyModel({ onSelect }) {
  const [selectedIds, setSelectedIds] = useState([]);
  const [selectedLabels, setSelectedLabels] = useState([]);

  function toggle(id, label) {
    setSelectedIds(prev => {
      const next = prev.includes(id) ? prev.filter(x => x !== id) : [...prev, id];
      const newLabels = next.map(nid => {
        const all = [...FRONT_PARTS, ...BACK_PARTS];
        return all.find(p => p.id === nid)?.label;
      }).filter(Boolean);
      setSelectedLabels(newLabels);
      if (onSelect) onSelect(newLabels);
      return next;
    });
  }

  function remove(label) {
    const part = [...FRONT_PARTS, ...BACK_PARTS].find(p => p.label === label);
    if (part) toggle(part.id, part.label);
  }

  return (
    <div className="body-model-area">
      <p className="body-model-label">Bitte tippen Sie auf die Stelle, wo Sie Schmerzen haben</p>
      <div className="body-model-views">
        <BodySVG parts={FRONT_PARTS} selected={selectedIds} onToggle={toggle} label="Vorderseite" />
        <BackBodySVG parts={BACK_PARTS}  selected={selectedIds} onToggle={toggle} label="Rückseite" />
      </div>
      {selectedLabels.length > 0 && (
        <div className="body-selected-parts">
          {selectedLabels.map(l => (
            <div key={l} className="body-part-tag">
              {l}
              <button onClick={() => remove(l)}>&times;</button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
